import React, { useState } from "react";
import CheckoutLine from "./checkout-line";
import "./checkout-form.css";
import "./modal.css";
import Spinner from "./spinner";
import * as jose from 'jose'

import { ALG, PUBLIC_KEY, EMAIL } from "../config/shop";

export function CheckoutModal({image, title, description, quantity, price, currency, shipping, show}){
	return(
		<div id="modal" >
		<div id="modal-inner" style={{textAlign:`center`}} >

		<CheckoutTabs
		paymentComponent={ <><CheckoutLine
			image={ image }
			title={ title }
			description={ description }
			quantity={ quantity }
			price={ price }
			currency={ currency }
			shipping={ shipping }
			total={ price + shipping }
			/><CheckoutForm title={title} quantity={quantity} /></> }
		crypto1={ <Spinner size={150}/> } />

		<button type="button"
		onClick={ e=> show( false ) }
		className="close-button"
		target="_blank"
		rel="noopener noreferrer"
		style={{
			margin: "4px",
				display: "block",
				padding: "12px 20px",
				borderRadius: "6px",
				textDecoration: "none",
				fontWeight: "bold",
		}} >
		Back
		</button>

		</div>
		</div> );
}

export function CheckoutTabs({
	paymentComponent,
	crypto1,
	crypto2,
}) {
	const [active, setActive] = useState("payment");

	return (
		<div className="checkout">
		<div className="checkout-heading">
			<span className="checkout-eyebrow">Secure checkout</span>
			<h2>Complete your order</h2>
			<p>Enter your delivery details to continue.</p>
		</div>
		<div className="checkout-tabs">
		<button
		type="button"
		className={active === "payment" ? "active" : ""}
		onClick={() => setActive("payment")} >
		Checkout
		</button>
		<button
		type="button"
		className={active === "crypto1" ? "active" : ""}
		onClick={() => setActive("crypto1")} >
		Bank
		</button>
		</div>
		<div className="checkout-content">
		{active === "payment" && paymentComponent}
		{active === "crypto1" && crypto1}
		{active === "crypto2" && crypto2}
		</div>
		</div>
	);
}

export function CheckoutForm({ title, quantity }){

	const [formData, setFormData] = useState({
		title: title,
		quantity: quantity,
		address: "",
		postcode: "",
		message: ""
	});

	const [serialised, setSerialized] = useState( null );
	const [isSubmitting, setIsSubmitting] = useState(false);

	async function encrypt( txt  ) {
		setIsSubmitting(true);
		try {
			const _publicKey = await jose.importSPKI(  PUBLIC_KEY , ALG  )
			const jwe = await new jose.CompactEncrypt(
				new TextEncoder().encode( txt )
			)
				.setProtectedHeader({ alg: 'RSA-OAEP-256', enc: 'A256GCM' })
				.encrypt( _publicKey )

			setSerialized(jwe)
		} finally {
			setIsSubmitting(false);
		}

	}

	const handleChange = (e) => {
		const { name, value } = e.target;
		setFormData((prev) => ({ ...prev, [name]: value }));
	};

	const handleSubmit = (e) => {
		e.preventDefault();
		console.log("Form submitted:", formData);
	};

	const SerialData = ({text}) => {
		const [copied, setCopied] = useState(false);

		const copy = () => {
			navigator.clipboard.writeText(text);
			setCopied(true);
			setTimeout(() => setCopied(false), 2000);
		};

		return(
			<><div
			role="button"
			tabIndex="0"
			aria-label="Copy encrypted order data"
			style={{
				wordBreak: "break-all",
					cursor: "pointer",
					fontSize: "0.9rem",
					background: "#f6f6f6",
					padding: "0.7rem",
					borderRadius: "8px",
			}}
			onClick={copy}
			>
			<span>{text}</span>
			<span className="copy-status">{copied ? "Copied" : "Copy"} <span aria-hidden="true">📋</span></span>
			</div>
			<a
			href={`mailto:${EMAIL}?subject=Order&body=${text}`} 
			className="submit-button email-button"
			>
			E-mail
			</a></>


		);

	} 

	return ( <>
		{ serialised ? <SerialData text={serialised} /> : <form
			className="checkout-form" onSubmit={handleSubmit}>
			<div className="form-intro">
				<span className="form-step">Step 1 of 1</span>
				<h3>Delivery details</h3>
			</div>
			<label>
			<span>Delivery address <span aria-hidden="true">*</span></span>
			<input
			type="text"
			name="address"
			value={formData.address}
			onChange={handleChange}
			required
			placeholder="Street, town or city"
			/>
			</label>

			<label>
			<span>Postcode <span aria-hidden="true">*</span></span>
			<input
			type="text"
			name="postcode"
			value={formData.postcode}
			onChange={handleChange}
			required
			placeholder="e.g. SW1A 1AA"
			/>
			</label>

			<label>
			<span>Note <small>Optional</small></span>
			<textarea
			name="message"
			value={formData.message}
			onChange={handleChange}
			placeholder="Add a note about your order"
			rows={4}
			/>
			</label>

			<button type="submit"
			onClick={ e => encrypt( JSON.stringify( formData ) ) } 
			disabled={isSubmitting}
			className="submit-button">
			{isSubmitting ? "Securing order…" : "Continue securely"}
			</button>
			<p className="form-footnote"><span aria-hidden="true">🔒</span> Your details are encrypted before they leave this page.</p>
			</form> } </>
	);
}
